19	import org.springframework.stereotype.Service;
20	import org.springframework.transaction.annotation.Transactional;
21	
22	/** The claims people on a sheet make. */
23	@Service
24	public class ClaimService {
25	
26	    /** Written for a due that has no rate to work from. */
27	    private static final String NO_RATE = "n/a";
28	
29	    private final ClaimRepository claims;
30	    private final PersonRepository people;
31	    private final RateService rates;
32	    private final SheetService sheets;
33	    private final PeriodRepository periods;
34	    private final SettingService settings;
35	    private final Audit audit;
36	
37	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
38	            PeriodRepository periods, SettingService settings, Audit audit) {
39	        this.periods = periods;
40	        this.settings = settings;
41	        this.claims = claims;
42	        this.people = people;
43	        this.rates = rates;
44	        this.sheets = sheets;
45	        this.audit = audit;
46	    }
47	
48	    /** The sheet's claims, newest first. */
49	    public List<Claim> list(String sheetId) {
50	        return claims.findBySheetIdOrderByIdDesc(sheetId);
51	    }
52	
53	    /** Add a claim for a person; a missing date takes the sheet's today. */
54	    @Transactional
55	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note) {
56	        Person person = person(sheetId, personId);
57	        LocalDate on = date != null ? date : sheets.today(sheetId);
58	        refuseClosed(sheetId, on);
59	        refuseRetired(person, on);
60	        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), on, noteOf(note)));
61	        record("CLAIM_ADDED", sheetId, user, person, added);
62	        return added;
63	    }
64	
65	    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today. Any
66	     *  other claim is refused: an OPEN one is changed by voiding it and adding a new one. */
67	    @Transactional
68	    public Claim update(String sheetId, String user, Long personId, Long id, BigDecimal amount, LocalDate date,
69	            String note) {
70	        Person person = person(sheetId, personId);
71	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
72	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
73	        if (claim.getStatus() != ClaimStatus.DRAFT) {
74	            throw new ClaimNotEditableException(claim.getStatus());
75	        }
76	        LocalDate on = date != null ? date : sheets.today(sheetId);
77	        refuseClosed(sheetId, claim.getDate());
78	        refuseClosed(sheetId, on);
79	        refuseRetired(person, on);
80	        claim.setAmount(scaled(amount));
81	        claim.setDate(on);
82	        claim.setNote(noteOf(note));
83	        Claim saved = claims.saveAndFlush(claim);
84	        record("CLAIM_EDITED", sheetId, user, person, saved);
85	        return saved;
86	    }
87	
88	    /** Move a claim to a new status; a change its status does not allow is refused, as is the user
89	     *  who opened a claim settling it, and a clerk settling a claim whose due is above the clerk
90	     *  limit. */
91	    @Transactional
92	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
93	        Person person = person(sheetId, personId);
94	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
95	        // read below is its latest state.
96	        Long number = to == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
97	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
98	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
99	        refuseClosed(sheetId, claim.getDate());
100	        if (!claim.getStatus().canMoveTo(to)) {
