1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Component, inject, input, output, signal } from '@angular/core';
3	import { firstValueFrom } from 'rxjs';
4	import { Session } from '../../core/session';
5	import { PeriodStore, periodOf } from '../periods/periods';
6	import { NO_RATE, Rate, dueCents, rateOn } from '../rates/rates';
7	
8	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID. */
9	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
10	
11	/** A status change a claim's buttons ask for. */
12	type ClaimAction = 'open' | 'settle' | 'void';
13	
14	export interface Claim {
15	  id: number;
16	  personId: number;
17	  /** Two decimals, e.g. "10.00". */
18	  amount: string;
19	  date: string;
20	  note: string;
21	  status: ClaimStatus;
22	  /** The claim's number on the sheet, given when it is opened and kept when it is voided; null for a
23	   *  claim never opened. */
24	  number: number | null;
25	  /** The due fixed when the claim was settled (two decimals); null until then, or when its grade
26	   *  had no rate to work from. */
27	  settledDue: string | null;
28	  /** The user who opened the claim; null for a claim never opened. */
29	  openedBy: string | null;
30	  /** Whether the person's last statement bound the claim to the figure it had then. */
31	  stated: boolean;
32	  /** The figure the statement bound the claim to (two decimals); null when unbound or it had none. */
33	  statedDue: string | null;
34	}
35	
36	/** Whether a claim counts toward what is claimed and due: only OPEN and SETTLED ones do. */
37	export function counts(claim: Claim): boolean {
38	  return claim.status === 'OPEN' || claim.status === 'SETTLED';
39	}
40	
41	/** An amount in cents, from the two-decimal string the server sends. */
42	export function cents(amount: string): number {
43	  return Math.round(Number(amount) * 100);
44	}
45	
46	/** A claim's due in cents: the due fixed when it was settled; otherwise the figure a statement
47	 *  bound it to; otherwise its amount times the rate in force on its date among its grade's rates,
48	 *  raised to the sheet's floor (in cents); null when it has no figure. */
49	export function claimDueCents(claim: Claim, rates: Rate[], floor: number): number | null {
50	  if (claim.settledDue !== null) return cents(claim.settledDue);
51	  if (claim.stated) return claim.statedDue === null ? null : cents(claim.statedDue);
52	  const rate = rateOn(rates, claim.date);
53	  return rate === null ? null : Math.max(dueCents(cents(claim.amount), rate), floor);
54	}
55	
56	/** The date a claim is due by (yyyy-mm-dd): its date plus the terms in days. */
57	export function dueByOf(claim: Claim, terms: number): string {
58	  const [y, m, d] = claim.date.split('-').map(Number);
59	  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
60	}
61	
62	/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
63	export function overdue(claim: Claim, terms: number, today: string | null): boolean {
64	  return claim.status === 'OPEN' && today !== null && dueByOf(claim, terms) < today;
65	}
66	
67	/** Cents shown with two decimals. */
68	export function money(total: number): string {
69	  return (total / 100).toFixed(2);
70	}
71	
72	const PAST: Record<ClaimAction, string> = { open: 'opened', settle: 'settled', void: 'voided' };
73	
74	/** An amount of 0.00 or more with up to two decimals. */
75	export const AMOUNT = /^\d+(\.\d{1,2})?$/;
76	
77	// A person's claims, newest first, and the one form that adds a claim or, once a claim's editor is
78	// opened, saves its changes.
79	@Component({
80	  selector: 'app-person-claims',
