92	          (input)="quickAmount.set(value($event)); quickError.set(null)"
93	        />
94	        <button type="submit" data-testid="quick-submit">Quick add</button>
95	      </form>
96	      @if (quickError(); as message) {
97	        <p role="alert" data-testid="quick-error">{{ message }}</p>
98	      }
99	      <label>
100	        <input
101	          type="checkbox"
102	          data-testid="show-retired"
103	          [checked]="showRetired()"
104	          (change)="showRetired.set(checked($event))"
105	        />
106	        Show retired
107	      </label>
108	      <p>Claimed in total <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
109	      <p>Due in total <strong data-testid="rollup-due-total">{{ dueTotal() }}</strong></p>
110	      <p>Overdue claims <strong data-testid="rollup-overdue-count">{{ overdueCount() }}</strong></p>
111	      <p>Overdue in total <strong data-testid="rollup-overdue-total">{{ overdueTotal() }}</strong></p>
112	
113	      <table>
114	        <thead>
115	          <tr>
116	            <th scope="col">Name</th>
117	            <th scope="col">Grade</th>
118	            <th scope="col">Claimed</th>
119	            <th scope="col">Due</th>
120	            <th scope="col">Overdue</th>
121	            <th scope="col">Overdue due</th>
122	            <th scope="col">Statements</th>
123	            <th scope="col">Last stated</th>
124	            <th scope="col">Stated on</th>
125	            <th scope="col">Retired</th>
126	            <th scope="col">Retired from</th>
127	            <th scope="col">On hold</th>
128	            <th scope="col">Claims</th>
129	            <th scope="col"><span class="visually-hidden">Actions</span></th>
130	          </tr>
131	        </thead>
132	        <tbody>
133	          @for (p of shownPeople(); track p.id) {
134	            <tr [attr.data-testid]="'person-row-' + p.id">
135	              <td data-testid="person-name">{{ p.name }}</td>
136	              <td data-testid="person-grade">{{ p.grade }}</td>
137	              <td data-testid="person-claimed">{{ claimedBy(p.id) }}</td>
138	              <td data-testid="person-due-total">{{ dueBy(p) }}</td>
139	              <td data-testid="person-overdue-count">{{ overdueOf(p.id).length }}</td>
140	              <td data-testid="person-overdue-total">{{ overdueTotalOf(p) }}</td>
141	              <td data-testid="person-statement-count">{{ p.statementCount }}</td>
142	              <td data-testid="person-stated-total">{{ p.statedTotal ?? '' }}</td>
143	              <td data-testid="person-statement-date">{{ p.statementDate ?? '' }}</td>
144	              <td data-testid="person-retired">{{ p.retired ? 'yes' : 'no' }}</td>
145	              <td data-testid="person-retired-from">{{ p.retiredFrom ?? '' }}</td>
146	              <td data-testid="person-hold">{{ p.held ? 'yes' : 'no' }}</td>
147	              <td>
148	                <app-person-claims
149	                  [personId]="p.id"
150	                  [claims]="claimsOf(p.id)"
151	                  [rates]="rates.of(p.grade)"
152	                  [floor]="floor()"
153	                  [terms]="settings.terms()"
154	                  (saved)="claimSaved($event)"
155	                />
156	              </td>
157	              <td>
158	                <button
159	                  type="button"
160	                  [attr.data-testid]="'person-edit-' + p.id"
161	                  [attr.aria-label]="'Edit ' + p.name"
162	                  (click)="edit(p)"
163	                >
164	                  Edit
165	                </button>
166	                <button
167	                  type="button"
168	                  data-testid="person-statement"
169	                  [attr.aria-label]="'Take a statement for ' + p.name"
170	                  (click)="takeStatement(p)"
171	                >
172	                  Statement
173	                </button>
174	                <label [for]="'person-retire-date-' + p.id">Retire from</label>
175	                <input
176	                  type="date"
177	                  [id]="'person-retire-date-' + p.id"
178	                  data-testid="person-retire-date"
179	                  [value]="retireDates()[p.id] ?? ''"
180	                  (input)="setRetireDate(p.id, value($event))"
181	                />
182	                <button
183	                  type="button"
184	                  data-testid="person-retire"
185	                  [attr.aria-label]="'Retire ' + p.name"
186	                  (click)="retire(p)"
187	                >
188	                  Retire
189	                </button>
190	                <button
191	                  type="button"
192	                  data-testid="person-hold-toggle"
193	                  [attr.aria-label]="(p.held ? 'Release ' : 'Hold ') + p.name"
194	                  (click)="toggleHold(p)"
195	                >
196	                  {{ p.held ? 'Release' : 'Hold' }}
197	                </button>
198	                @if (rowError(); as e) {
199	                  @if (e.id === p.id) {
200	                    <p role="alert" data-testid="person-error">{{ e.message }}</p>
201	                  }
202	                }
203	              </td>
204	            </tr>
205	          }
206	        </tbody>
207	      </table>
208	    </section>
209	  `,
210	})
211	export class People {
212	  private readonly http = inject(HttpClient);
213	  private readonly session = inject(Session);
214	  protected readonly rates = inject(RateStore);
215	  private readonly periods = inject(PeriodStore);
216	  protected readonly settings = inject(SettingStore);
217	  /** The sheet's floor in cents. */
218	  protected readonly floor = computed(() => cents(this.settings.floor()));
219	
220	  protected readonly grades = ['A', 'B', 'C'];
221	  protected readonly people = signal<Person[]>([]);
222	  /** Whether retired people are listed; off when the screen opens and kept across sheet loads. */
223	  protected readonly showRetired = signal(false);
224	  /** The people listed: everyone, or only those not retired unless retired people are shown. */
225	  protected readonly shownPeople = computed(() =>
226	    this.showRetired() ? this.people() : this.people().filter((p) => !p.retired),
227	  );
228	  /** The retirement date typed on each person's row, by person id. */
229	  protected readonly retireDates = signal<Record<number, string>>({});
230	  /** The sheet's claims, newest first. */
231	  protected readonly claims = signal<Claim[]>([]);
232	  /** The sheet's claims that count in live totals: OPEN and SETTLED ones, except a held person's
233	   *  OPEN ones. */
234	  private readonly live = computed(() => {
235	    const held = new Set(this.people().filter((p) => p.held).map((p) => p.id));
236	    return this.claims().filter((c) => counts(c) && !(c.status === 'OPEN' && held.has(c.personId)));
237	  });
238	  /** Each person's claims that count toward what is claimed and due, by person id. */
239	  private readonly countedByPerson = computed(() => {
240	    const map = new Map<number, Claim[]>();
241	    for (const c of this.live()) map.set(c.personId, [...(map.get(c.personId) ?? []), c]);
242	    return map;
243	  });
244	  /** Each person's claims, newest first, by person id. */
245	  private readonly claimsByPerson = computed(() => {
246	    const map = new Map<number, Claim[]>();
247	    for (const c of this.claims()) map.set(c.personId, [...(map.get(c.personId) ?? []), c]);
248	    return map;
249	  });
250	  protected readonly claimedTotal = computed(() =>
251	    money(this.live().reduce((sum, c) => sum + cents(c.amount), 0)),
252	  );
253	  /** Everyone's due-total added up, skipping those whose grade has no rate. */
254	  protected readonly dueTotal = computed(() =>
255	    money(
256	      this.people().reduce((sum, p) => {
257	        const due = this.dueCentsBy(p);
258	        return due === null ? sum : sum + due;
259	      }, 0),
260	    ),
261	  );
262	  /** Each person's claims that count and are overdue, by person id. */
263	  private readonly overdueByPerson = computed(() => {
264	    const terms = this.settings.terms();
265	    const today = this.session.today();
266	    const map = new Map<number, Claim[]>();
267	    for (const c of this.live()) {
268	      if (overdue(c, terms, today)) map.set(c.personId, [...(map.get(c.personId) ?? []), c]);
269	    }
270	    return map;
271	  });
272	  /** How many claims that count are overdue on the sheet. */
273	  protected readonly overdueCount = computed(() =>
274	    [...this.overdueByPerson().values()].reduce((n, list) => n + list.length, 0),
275	  );
276	  /** The dues of the sheet's overdue claims that count added up. */
277	  protected readonly overdueTotal = computed(() =>
278	    money(this.people().reduce((sum, p) => sum + this.overdueCentsOf(p), 0)),
279	  );
280	  /** Each period's due-total, by period id: the dues shown on the claims that count in live totals
281	   *  whose date falls in the period (a claim with no figure adds nothing). */
282	  protected readonly periodDueTotals = computed(() => {
283	    const periods = this.periods.periods();
284	    const grades = new Map(this.people().map((p) => [p.id, p.grade]));
285	    const totals = new Map<number, number>(periods.map((p) => [p.id, 0]));
286	    for (const c of this.live()) {
287	      const period = periodOf(periods, c.date);
288	      const grade = grades.get(c.personId);
289	      if (period === null || grade === undefined) continue;
290	      totals.set(period.id, (totals.get(period.id) ?? 0) + (claimDueCents(c, this.rates.of(grade), this.floor()) ?? 0));
291	    }
292	    return new Map([...totals].map(([id, due]) => [id, money(due)]));
293	  });
294	  protected readonly name = signal('');
295	  protected readonly grade = signal('A');
296	  protected readonly editingId = signal<number | null>(null);
297	  /** The version of the person the editor loaded. */
298	  private readonly editingVersion = signal(0);
299	  /** Whether a submit is waiting for its answer; a second submit meanwhile is dropped. */
300	  private readonly busy = signal(false);
301	  protected readonly error = signal<string | null>(null);
302	  protected readonly quickName = signal('');
303	  protected readonly quickAmount = signal('');
304	  /** Whether a quick-add is waiting for its answer; a second one meanwhile is dropped. */
305	  private readonly quickBusy = signal(false);
306	  protected readonly quickError = signal<string | null>(null);
307	  /** The error from the last action on a person's row refused, and the person it belongs to. */
308	  protected readonly rowError = signal<{ id: number; message: string } | null>(null);
309	
310	  constructor() {
311	    effect(() => {
312	      const sheet = this.session.sheetId();
313	      const load = this.session.loads();
314	      this.people.set([]);
315	      this.claims.set([]);
316	      this.rowError.set(null);
317	      this.retireDates.set({});
318	      this.reset();
319	      this.quickName.set('');
320	      this.quickAmount.set('');
321	      this.quickError.set(null);
322	      if (sheet) void this.read(sheet, load);
323	    });
324	  }
325	
326	  protected value(event: Event): string {
327	    return (event.target as HTMLInputElement | HTMLSelectElement).value;
328	  }
329	
330	  protected checked(event: Event): boolean {
331	    return (event.target as HTMLInputElement).checked;
332	  }
333	
334	  protected setRetireDate(personId: number, date: string): void {
335	    this.retireDates.update((dates) => ({ ...dates, [personId]: date }));
336	    if (this.rowError()?.id === personId) this.rowError.set(null);
337	  }
338	
339	  /** Retire a person from the typed date (blank takes the sheet's today); their row then shows it,
340	   *  or leaves the list while retired people are not shown. */
341	  protected async retire(person: Person): Promise<void> {
342	    this.rowError.set(null);
343	    const sheet = this.session.sheetId();
344	    if (!sheet) return;
345	    const from = (this.retireDates()[person.id] ?? '').trim() || null;
346	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`;
347	    try {
348	      const saved = await firstValueFrom(this.http.post<Person>(url, { from }));
349	      if (this.session.sheetId() !== sheet) return;
350	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
351	      this.retireDates.update((dates) => ({ ...dates, [person.id]: '' }));
352	    } catch {
353	      this.rowError.set({ id: person.id, message: `${person.name} could not be retired.` });
354	    }
355	  }
356	
357	  /** Put a person on hold, or take them off hold; their row and the totals then show it. */
358	  protected async toggleHold(person: Person): Promise<void> {
359	    this.rowError.set(null);
360	    const sheet = this.session.sheetId();
361	    if (!sheet) return;
362	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/hold`;
363	    try {
364	      const saved = await firstValueFrom(this.http.post<Person>(url, null));
365	      if (this.session.sheetId() !== sheet) return;
366	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
367	    } catch {
368	      this.rowError.set({
369	        id: person.id,
370	        message: `${person.name} could not be ${person.held ? 'taken off hold' : 'put on hold'}.`,
371	      });
372	    }
373	  }
374	
375	  protected claimsOf(personId: number): Claim[] {
376	    return this.claimsByPerson().get(personId) ?? [];
377	  }
378	
379	  /** A person's OPEN and SETTLED claims; drafts and voided claims do not count. */
380	  private countedOf(personId: number): Claim[] {
381	    return this.countedByPerson().get(personId) ?? [];
382	  }
383	
384	  protected claimedBy(personId: number): string {
385	    return money(this.countedOf(personId).reduce((sum, c) => sum + cents(c.amount), 0));
386	  }
387	
388	  /** The sum of the dues shown on a person's claims that count, or n/a when their grade has no rate
389	   *  in force on the sheet's today and no settled or stated claim of theirs keeps a figure. */
390	  protected dueBy(person: Person): string {
391	    const due = this.dueCentsBy(person);
392	    return due === null ? NO_RATE : money(due);
393	  }
394	
395	  private dueCentsBy(person: Person): number | null {
396	    const counted = this.countedOf(person.id);
397	    const hasRate = this.rates.current().has(person.grade);
398	    if (!hasRate && !counted.some((c) => c.settledDue !== null || (c.stated && c.statedDue !== null))) {
399	      return null;
400	    }
401	    const rates = this.rates.of(person.grade);
402	    const floor = this.floor();
403	    return counted.reduce((sum, c) => sum + (claimDueCents(c, rates, floor) ?? 0), 0);
404	  }
405	
406	  protected overdueOf(personId: number): Claim[] {
407	    return this.overdueByPerson().get(personId) ?? [];
408	  }
409	
410	  /** The dues of a person's overdue claims that count added up (a claim with no figure adds nothing). */
411	  protected overdueTotalOf(person: Person): string {
412	    return money(this.overdueCentsOf(person));
413	  }
414	
415	  private overdueCentsOf(person: Person): number {
416	    const rates = this.rates.of(person.grade);
417	    const floor = this.floor();
418	    return this.overdueOf(person.id).reduce((sum, c) => sum + (claimDueCents(c, rates, floor) ?? 0), 0);
419	  }
420	
421	  /** A claim added (listed first) or saved in place. */
422	  protected claimSaved(saved: Claim): void {
423	    this.claims.update((list) =>
424	      list.some((c) => c.id === saved.id)
425	        ? list.map((c) => (c.id === saved.id ? saved : c))
426	        : [saved, ...list],
427	    );
428	  }
429	
430	  /** Take a statement for a person: their row and claims then show what it recorded and bound. */
431	  protected async takeStatement(person: Person): Promise<void> {
432	    this.rowError.set(null);
433	    const sheet = this.session.sheetId();
434	    if (!sheet) return;
435	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement`;
436	    try {
437	      const taken = await firstValueFrom(this.http.post<StatementTaken>(url, null));
438	      if (this.session.sheetId() !== sheet) return;
439	      const bound = new Map(taken.claims.map((c) => [c.id, c]));
440	      this.claims.update((list) => [
441	        ...taken.claims.filter((c) => !list.some((had) => had.id === c.id)),
442	        ...list.map((c) => bound.get(c.id) ?? c),
443	      ].sort((a, b) => b.id - a.id));
444	      const { count, lastDueTotal, lastDate } = taken.statements;
445	      this.people.update((list) =>
446	        list.map((p) =>
447	          p.id === person.id
448	            ? { ...p, statementCount: count, statedTotal: lastDueTotal, statementDate: lastDate }
449	            : p,
450	        ),
451	      );
452	    } catch {
453	      this.rowError.set({ id: person.id, message: `A statement could not be taken for ${person.name}.` });
454	    }
455	  }
456	
457	  protected edit(person: Person): void {
458	    this.rowError.set(null);
459	    this.editingId.set(person.id);
460	    this.editingVersion.set(person.version);
461	    this.name.set(person.name);
462	    this.grade.set(person.grade);
463	    this.error.set(null);
464	  }
465	
466	  protected reset(): void {
467	    this.editingId.set(null);
468	    this.name.set('');
469	    this.grade.set('A');
470	    this.error.set(null);
471	  }
472	
473	  protected async submit(event: Event): Promise<void> {
474	    event.preventDefault();
475	    if (this.busy()) return;
476	    this.error.set(null);
477	    const sheet = this.session.sheetId();
478	    if (!sheet) return;
479	    const body = { name: this.name().trim(), grade: this.grade() };
480	    if (!body.name) {
481	      this.error.set('Type a name for the person.');
482	      return;
483	    }
484	    const id = this.editingId();
485	    const base = `/api/sheets/${encodeURIComponent(sheet)}/people`;
486	    this.busy.set(true);
487	    try {
488	      const saved = await firstValueFrom(
489	        id === null
490	          ? this.http.post<Person>(base, body)
491	          : this.http.put<Person>(`${base}/${id}`, { ...body, version: this.editingVersion() }),
492	      );
493	      if (this.session.sheetId() !== sheet) return;
494	      this.people.update((list) =>
495	        id === null ? [...list, saved] : list.map((p) => (p.id === saved.id ? saved : p)),
496	      );
497	      this.reset();
498	    } catch (e) {
499	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
500	        await this.showCurrent(sheet, id, e.error as Person | null);
501	        this.error.set('Someone else saved this person since you opened the editor; their values are shown.');
502	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
503	        this.error.set(`Another person on the sheet is already named ${body.name}.`);
504	      } else {
505	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
506	      }
507	    } finally {
508	      this.busy.set(false);
509	    }
510	  }
511	
512	  /** Add a DRAFT claim for the named person, adding them (grade A) when the name is not on the
513	   *  sheet; their row and the claim then show. */
514	  protected async quickAdd(event: Event): Promise<void> {
515	    event.preventDefault();
516	    if (this.quickBusy()) return;
517	    this.quickError.set(null);
518	    const sheet = this.session.sheetId();
519	    if (!sheet) return;
520	    const name = this.quickName().trim();
521	    const amount = this.quickAmount().trim();
522	    if (!name) {
523	      this.quickError.set('Type a name for the claim.');
524	      return;
525	    }
526	    if (!AMOUNT.test(amount)) {
527	      this.quickError.set('Type an amount of 0.00 or more, with up to two decimals.');
528	      return;
529	    }
530	    this.quickBusy.set(true);
531	    try {
532	      const added = await firstValueFrom(
533	        this.http.post<{ person: Person; claim: Claim }>(
534	          `/api/sheets/${encodeURIComponent(sheet)}/quick-add`,
535	          { name, amount },
536	        ),
537	      );
538	      if (this.session.sheetId() !== sheet) return;
539	      this.people.update((list) =>
540	        list.some((p) => p.id === added.person.id)
541	          ? list.map((p) => (p.id === added.person.id ? added.person : p))
542	          : [...list, added.person],
543	      );
544	      this.claimSaved(added.claim);
545	      this.quickName.set('');
546	      this.quickAmount.set('');
547	    } catch (e) {
548	      this.quickError.set(
549	        e instanceof HttpErrorResponse && e.status === 409
550	          ? `A claim for ${name} could not be added: its date falls in a closed period or after they retired.`
551	          : `A claim for ${name} could not be added.`,
552	      );
553	    } finally {
554	      this.quickBusy.set(false);
555	    }
556	  }
557	
558	  /** After a refused stale save, show the person as stored now, in their row and in the editor,
559	   *  which then holds the version it shows. */
560	  private async showCurrent(sheet: string, id: number, current: Person | null): Promise<void> {
561	    if (!current) {
562	      const list = await firstValueFrom(
563	        this.http.get<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
564	      ).catch(() => []);
565	      current = list.find((p) => p.id === id) ?? null;
566	    }
567	    if (!current || this.session.sheetId() !== sheet) return;
568	    const now = current;
569	    this.people.update((list) => list.map((p) => (p.id === now.id ? now : p)));
570	    if (this.editingId() === now.id) {
571	      this.editingVersion.set(now.version);
572	      this.name.set(now.name);
573	      this.grade.set(now.grade);
574	    }
575	  }
576	
577	  /** Read the sheet's people and claims; a response for an earlier load is dropped. */
578	  private async read(sheet: string, load: number): Promise<void> {
579	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
580	    const [list, claims] = await Promise.all([
581	      firstValueFrom(this.http.get<Person[]>(`${base}/people`)),
582	      firstValueFrom(this.http.get<Claim[]>(`${base}/claims`)),
583	    ]);
584	    if (this.session.loads() !== load) return;
585	    this.people.set(list);
586	    this.claims.set(claims);
587	  }
588	}
